CREATE TABLE maintenance_windows (id CHAR(36) PRIMARY KEY,project_id CHAR(36) NOT NULL,scope_type VARCHAR(16) NOT NULL,service_id CHAR(36),device_id VARCHAR(128),name VARCHAR(200) NOT NULL,reason VARCHAR(1000) NOT NULL,starts_at TIMESTAMP(6) NOT NULL,ends_at TIMESTAMP(6) NOT NULL,enabled BOOLEAN NOT NULL,created_by_user_id CHAR(36) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,CONSTRAINT chk_maintenance_range CHECK(ends_at>starts_at),CONSTRAINT chk_maintenance_scope CHECK((scope_type='PROJECT' AND service_id IS NULL AND device_id IS NULL) OR (scope_type='SERVICE' AND service_id IS NOT NULL AND device_id IS NULL) OR (scope_type='DEVICE' AND service_id IS NULL AND device_id IS NOT NULL)));
CREATE INDEX idx_maintenance_active_project ON maintenance_windows(project_id,enabled,starts_at,ends_at);CREATE INDEX idx_maintenance_service ON maintenance_windows(project_id,service_id,starts_at,ends_at);CREATE INDEX idx_maintenance_device ON maintenance_windows(project_id,device_id,starts_at,ends_at);
CREATE TABLE alert_suppression_history (id CHAR(36) PRIMARY KEY,project_id CHAR(36) NOT NULL,maintenance_window_id CHAR(36) NOT NULL,alert_rule_id CHAR(36) NOT NULL,rule_name VARCHAR(200) NOT NULL,source_type VARCHAR(16) NOT NULL,source_id VARCHAR(128) NOT NULL,metric_type VARCHAR(32) NOT NULL,observed_value DECIMAL(20,6) NOT NULL,threshold_value DECIMAL(20,6) NOT NULL,evaluated_at TIMESTAMP(6) NOT NULL,suppressed_at TIMESTAMP(6) NOT NULL,window_name VARCHAR(200) NOT NULL,reason VARCHAR(1000) NOT NULL,origin VARCHAR(32) NOT NULL,dedup_key CHAR(64) NOT NULL,CONSTRAINT uk_suppression_window_dedup UNIQUE(maintenance_window_id,dedup_key),CONSTRAINT fk_suppression_window FOREIGN KEY(maintenance_window_id) REFERENCES maintenance_windows(id));
CREATE INDEX idx_suppression_project_window ON alert_suppression_history(project_id,maintenance_window_id,suppressed_at);
CREATE TABLE maintenance_window_audit (id CHAR(36) PRIMARY KEY,project_id CHAR(36) NOT NULL,maintenance_window_id CHAR(36) NOT NULL,actor_user_id CHAR(36) NOT NULL,action VARCHAR(16) NOT NULL,occurred_at TIMESTAMP(6) NOT NULL);CREATE INDEX idx_maintenance_audit_window ON maintenance_window_audit(project_id,maintenance_window_id,occurred_at);
